from .common import *

def stages(c):
 return [S('service_entry',{'$option':'entryPoint','escape':'sql','template':'SELECT {} name'}),S('service_classes',"""SELECT n.*,CASE WHEN substr(n.name,-8)='Protocol' OR substr(n.name,-8)='Contract' OR substr(n.name,-4)='Plan' OR EXISTS(SELECT 1 FROM a b WHERE b.__path=n.__path AND b.parent=n.id AND b.field='bases' AND b.kind IN ('Name','Attribute') AND b.name IN ('Protocol','TypedDict')) THEN 1 ELSE 0 END AS abstract FROM a n WHERE kind='ClassDef' AND parent=0""",('__path','id')),
 S('service_methods',"SELECT m.*,c.abstract FROM methods m JOIN service_classes c ON c.__path=m.__path AND c.id=m.parent",('__path','id'),('__path','parent','name')),
 S('latest_methods',"SELECT m.*,(SELECT min(x.id) FROM service_methods x WHERE x.__path=m.__path AND x.parent=m.parent AND x.name=m.name) AS insertion FROM service_methods m WHERE NOT EXISTS(SELECT 1 FROM service_methods x WHERE x.__path=m.__path AND x.parent=m.parent AND x.name=m.name AND x.id>m.id)",('__path','parent','name'),('__path','id')),
 S('name_decorators',"SELECT * FROM decorators WHERE kind='Name'",('__path','fn','name')),
 S('slot_aliases',f"""SELECT n.__path,n.fn,t.name,n.id FROM a n JOIN a t ON t.__path=n.__path AND t.parent=n.id AND t.field IN ('target','targets') AND t.kind='Name' JOIN a v ON v.__path=n.__path AND v.parent=n.id AND v.field='value'
 WHERE n.kind IN ('Assign','AnnAssign') AND n.fn IS NOT NULL AND EXISTS(SELECT 1 FROM a k WHERE k.__path=v.__path AND k.id BETWEEN v.id AND v.last AND k.kind='Constant' AND k.value_kind='str' AND k.value IN {literals(c['SCHEMA_TRANSACTION_SLOT_NAMES'])})""",('__path','fn','name','id')),
 S('slot_probes',f"""SELECT c.*,v.name AS probe_name,v.name_repr AS probe_repr FROM calls c JOIN a v ON v.__path=c.__path AND v.parent=c.id AND v.field='args' AND v.position=CASE WHEN c.callee IN ('getattr','hasattr') THEN 1 ELSE 0 END
 WHERE (c.callee IN ('getattr','hasattr') OR c.callee_kind='Attribute' AND c.callee='get' AND EXISTS(SELECT 1 FROM calls receiver WHERE receiver.__path=c.__path AND receiver.id=c.receiver AND receiver.callee='vars'))
 AND v.kind='Name' AND EXISTS(SELECT 1 FROM slot_aliases s WHERE s.__path=c.__path AND s.fn=c.fn AND s.name=v.name AND s.id<c.id)
 UNION ALL SELECT c.*,v.value,v.value_repr FROM calls c JOIN a v ON v.__path=c.__path AND v.parent=c.id AND v.field='args' AND v.position=CASE WHEN c.callee IN ('getattr','hasattr') THEN 1 ELSE 0 END
 WHERE (c.callee IN ('getattr','hasattr') OR c.callee_kind='Attribute' AND c.callee='get' AND EXISTS(SELECT 1 FROM calls receiver WHERE receiver.__path=c.__path AND receiver.id=c.receiver AND receiver.callee='vars')) AND v.kind='Constant' AND v.value_kind='str' AND v.value IN {literals(c['SCHEMA_TRANSACTION_SLOT_NAMES'])}""",('__path','id')),
 S('delegates',"""SELECT m.__path,m.id FROM service_methods m JOIN bodies b ON b.__path=m.__path AND b.id=m.id JOIN body first ON first.__path=b.__path AND first.id=b.first_body JOIN body last ON last.__path=b.__path AND last.id=b.last_body
 LEFT JOIN a v ON v.__path=last.__path AND v.parent=last.id AND v.field='value'
 WHERE last.kind='Raise' OR b.body_count=1 AND (first.kind='Pass' OR first.kind='Expr' AND v.kind='Constant' AND v.value_kind='ellipsis')
 OR (b.body_count=1 AND first.kind IN ('Expr','Return') OR b.body_count=2 AND first.kind='Expr' AND last.kind='Return') AND (v.kind='Call' OR v.kind='Await' AND EXISTS(SELECT 1 FROM a x WHERE x.__path=v.__path AND x.parent=v.id AND x.field='value' AND x.kind='Call'))""",('__path','id')),
 S('owners',f"SELECT m.* FROM service_methods m LEFT JOIN delegates d ON d.__path=m.__path AND d.id=m.id WHERE NOT m.abstract AND (m.name IN {literals(c['OPERATIONAL_SCHEMA_METHODS'])} OR substr(m.name,1,8)='_schema_') AND d.id IS NULL",('__path','name'),('name',)),
 S('owner_groups',"SELECT __path,name,count(*) count,group_concat(class_name,', ') names FROM (SELECT * FROM owners ORDER BY id) GROUP BY __path,name",('__path','name')),
 S('legacy',"""SELECT m.*,d.name AS decorator,d.root AS decorator_id,CASE d.name WHEN 'legacy_sync' THEN '_legacy_delegate_stub' ELSE '_legacy_delegate_stub_async' END AS stub,
 coalesce(NULLIF((SELECT v.value FROM a k JOIN a v ON v.__path=k.__path AND v.parent=k.id AND v.field='value' JOIN name_decorators other ON other.__path=k.__path AND other.root=k.parent AND other.fn=m.id AND other.name=d.name WHERE k.__path=d.__path AND k.field='keywords' AND k.name='lazy_name' AND v.kind='Constant' AND v.value_kind='str' ORDER BY other.root,k.position LIMIT 1),''),CASE WHEN d.name='legacy_async' AND substr(m.name,-6)='_async' THEN substr(m.name,1,length(m.name)-6)||'_lazy' ELSE m.name||'_lazy' END) AS lazy_name
 FROM latest_methods m JOIN (SELECT __path,fn,name,min(root) root FROM name_decorators GROUP BY __path,fn,name) d ON d.__path=m.__path AND d.fn=m.id WHERE NOT m.abstract AND d.name IN ('legacy_sync','legacy_async') AND CASE WHEN (SELECT name FROM service_entry) NOT IN ('all','lint','analyze_source') OR m.abstract THEN 1 WHEN (SELECT count(DISTINCT check_decorator.name) FROM name_decorators check_decorator WHERE check_decorator.__path=m.__path AND check_decorator.fn=m.id AND check_decorator.name IN ('legacy_sync','legacy_async'))<=1 THEN 1 ELSE json_extract('[]','$[legacy decorator cardinality]') END""",('__path','id')),
 S('lazy_counterparts',"""SELECT l.__path,l.id,coalesce(own.id,fallback.id) AS counterpart FROM legacy l LEFT JOIN latest_methods own ON own.__path=l.__path AND own.parent=l.parent AND own.name=l.lazy_name
 LEFT JOIN latest_methods fallback ON fallback.__path=l.__path AND fallback.class_name='LazySchemaTransaction' AND fallback.name=l.lazy_name AND l.class_name IN ('SyncSchemaTransaction','AsyncSchemaTransaction') AND fallback.parent=(SELECT min(c.id) FROM service_classes c WHERE c.__path=l.__path AND c.name='LazySchemaTransaction')""",('__path','id')),
 S('first_classes',"SELECT c.* FROM service_classes c WHERE NOT EXISTS(SELECT 1 FROM service_classes x WHERE x.__path=c.__path AND x.name=c.name AND x.id<c.id)",('__path','name')),
 S('first_methods',"SELECT m.* FROM service_methods m JOIN first_classes c ON c.__path=m.__path AND c.id=m.parent WHERE NOT EXISTS(SELECT 1 FROM service_methods x WHERE x.__path=m.__path AND x.parent=m.parent AND x.name=m.name AND x.id<m.id)",('__path','class_name','name'))]

def analyze(c):
 sql=[]
 for code,table,condition,msg in [
 ('CONN102','functions',f"n.name IN {literals(c['FORBIDDEN_SCHEMA_TRANSACTION_LOOKUP_HELPERS'])}","'forbidden ambient schema transaction lookup helper '||n.name_repr||'; pass schema authority explicitly'"),
 ('CONN600','functions',f"n.name IN {literals(c['IMMEDIATE_BOOTSTRAP_METADATA_READER_NAMES'])}","'immediate bootstrap metadata reader '||n.name_repr||' bypasses the interrogation plan'"),
 ('CONN101','a',f"n.kind='Attribute' AND n.context='Load' AND n.name IN {literals(c['SCHEMA_TRANSACTION_SLOT_NAMES'])}","'direct schema transaction slot read '||n.name_repr||'; pass schema authority explicitly'"),
 ('CONN102','calls',f"n.callee IN {literals(c['FORBIDDEN_SCHEMA_TRANSACTION_LOOKUP_HELPERS'])}","'forbidden ambient schema transaction lookup helper call '||(SELECT a.name_repr FROM a WHERE a.__path=n.__path AND a.id=n.callee_id)||'; pass schema authority explicitly'"),
 ('CONN500','calls',f"n.callee='load_python_module' AND n.__path NOT IN {literals(c['ALLOWED_DEFERRED_IMPORT_MODULES'])}",q('connection code must not add scattered load_python_module shims; use the deferred-import boundary'))]:sql.append(row(code,msg,table+' n',condition))
 sql.append(row('CONN102',"'forbidden ambient schema transaction lookup helper import '||s.name_repr||'; pass schema authority explicitly'",'a n JOIN a s ON s.__path=n.__path AND s.parent=n.id',f"n.kind='ImportFrom' AND s.kind='alias' AND s.name IN {literals(c['FORBIDDEN_SCHEMA_TRANSACTION_LOOKUP_HELPERS'])}",order='n.id+s.position*0.00001'))
 sql.append(row('CONN100',"CASE WHEN n.callee='get' THEN 'vars(...).get' ELSE n.callee END||' probe of schema transaction slot '||n.probe_repr||'; pass schema authority explicitly'",'slot_probes n',order='n.id+0.0001'))
 sql.append(row('CONN601',"'read-through getattr delegation to '||v.name_repr||' treats connections as capability bags'",'calls n JOIN a v ON v.__path=n.__path AND v.parent=n.id AND v.field=\'args\' AND v.position=0',"n.__path='impl/read_through/connection.py' AND n.callee='getattr' AND v.kind='Attribute' AND v.name IN ('_cache','_upstream') AND "+child('v','value',alias='x',condition="x.kind='Name' AND x.name='self'"),order='n.id+0.0003'))
 related=f"n.name IN {literals(c['OPERATIONAL_SCHEMA_METHODS'])} OR substr(n.name,1,8)='_schema_' OR "+' OR '.join('instr(n.name,'+q(x)+')>0' for x in ['schema','versioned','polymorphic','large_column','column_exists'])
 sql.append(row('CONN200',"n.class_name||'.'||n.name||'/'||n.name||'_async are substantial sync/async twins; factor shared pure/lazy logic'",'latest_methods n JOIN latest_methods async ON async.__path=n.__path AND async.parent=n.parent AND async.name=n.name||\'_async\' JOIN bodies b ON b.__path=n.__path AND b.id=n.id JOIN bodies ab ON ab.__path=async.__path AND ab.id=async.id',f"NOT n.abstract AND n.class_name NOT IN ('LazySchemaTransaction','SyncSchemaTransaction','AsyncSchemaTransaction') AND substr(n.name,-6)!='_async' AND ({related}) AND b.body_count>=5 AND ab.body_count>=5",phase=1,order='n.insertion'))
 probe=desc('n',alias='probe',condition=named(c['COLUMN_SCHEMA_PROBE_MARKERS'],alias='probe'))
 sql.append(row('CONN103',"n.class_name||'.'||n.name||' is a connection-level column/schema probe; use explicit schema authority'",'service_methods n',"instr(n.class_name,'Connection')>0 AND substr(n.name,1,1)!='_' AND ("+probe+" OR n.kind='AsyncFunctionDef' AND "+child('n','returns',condition="v.kind='Name' AND v.name='bool'")+" AND EXISTS(SELECT 1 FROM parameters p WHERE p.__path=n.__path AND p.fn=n.id AND p.kind='arg' AND p.field='args' AND p.name='table_name') AND EXISTS(SELECT 1 FROM parameters p WHERE p.__path=n.__path AND p.fn=n.id AND p.kind='arg' AND p.field='args' AND p.name='column_name'))",phase=2))
 sql.append(row('CONN300',"n.name_repr||' has multiple non-delegate owners in one connection surface: '||g.names",'owners n JOIN owner_groups g ON g.__path=n.__path AND g.name=n.name',"g.count>1 AND substr(n.class_name,-7)!='Service'",phase=3,sort_name='n.name'))
 # Other UNION arms must carry the same extra ordering column.
 stub="EXISTS(SELECT 1 FROM bodies b JOIN body s ON s.__path=b.__path AND s.id=b.first_body JOIN calls call ON call.__path=s.__path AND call.parent=s.id AND call.field='value' WHERE b.__path=n.__path AND b.id=n.id AND b.body_count=1 AND s.kind='Expr' AND call.callee=n.stub)"
 assertion="EXISTS(SELECT 1 FROM bodies b JOIN body s ON s.__path=b.__path AND s.id=b.first_body JOIN calls call ON call.__path=s.__path AND call.parent=s.id AND call.field='exc' JOIN a msg ON msg.__path=call.__path AND msg.parent=call.id AND msg.field='args' AND msg.position=0 WHERE b.__path=n.__path AND b.id=n.id AND b.body_count=1 AND s.kind='Raise' AND call.callee='AssertionError' AND msg.kind='Constant' AND msg.value_kind='str' AND instr(msg.value,'legacy delegate should be provided by decorator')>0)"
 sql.extend([row('CONN400',"n.class_name||'.'||n.name||' must use '||n.stub||'() as its decorated legacy body'||CASE WHEN "+assertion+" THEN '; assertion-style stubs are not allowed' ELSE '' END",'legacy n','NOT '+stub,phase=4,order='n.insertion'),
 row('CONN401',"n.class_name||'.'||n.name||' legacy wrapper missing lazy counterpart '||n.lazy_name",'legacy n JOIN lazy_counterparts l ON l.__path=n.__path AND l.id=n.id','l.counterpart IS NULL',phase=4,order='n.insertion+0.0001'),
 row('CONN402',"n.class_name||'.'||n.lazy_name||' must be @pure_lazy for legacy wrapper '||n.name",'legacy n JOIN lazy_counterparts l ON l.__path=n.__path AND l.id=n.id JOIN a lazy ON lazy.__path=l.__path AND lazy.id=l.counterpart',"NOT EXISTS(SELECT 1 FROM name_decorators d WHERE d.__path=l.__path AND d.fn=l.counterpart AND d.name='pure_lazy')",phase=4,order='n.insertion+0.0001').replace('n.__start AS start_byte,n.__end AS end_byte,n.line,','lazy.__start AS start_byte,lazy.__end AS end_byte,lazy.line,',1)])
 return sql

def facade():
 names=['LazySchemaTransaction','SyncSchemaTransaction','AsyncSchemaTransaction']
 missing=' UNION ALL '.join(f'SELECT {i} ordinal,{q(name)} name' for i,name in enumerate(names))
 checks=[('ensure_polymorphic_columns_exist logic must live in pure_lazy ensure_polymorphic_columns_exist_lazy',"NOT EXISTS(SELECT 1 FROM first_methods m JOIN name_decorators d ON d.__path=m.__path AND d.fn=m.id AND d.name='pure_lazy' WHERE m.__path=n.__path AND m.class_name='LazySchemaTransaction' AND m.name='ensure_polymorphic_columns_exist_lazy')"),
 ('SyncSchemaTransaction must not restore eager ensure_polymorphic_columns_exist; use ensure_polymorphic_columns_exist_lazy at an explicit terminal boundary',"EXISTS(SELECT 1 FROM first_methods m WHERE m.__path=n.__path AND m.class_name='SyncSchemaTransaction' AND m.name='ensure_polymorphic_columns_exist')"),
 ('AsyncSchemaTransaction.ensure_polymorphic_columns_exist_async must be a legacy_async wrapper',"NOT EXISTS(SELECT 1 FROM first_methods m JOIN name_decorators d ON d.__path=m.__path AND d.fn=m.id AND d.name='legacy_async' JOIN a k ON k.__path=d.__path AND k.parent=d.root AND k.field='keywords' AND k.name='lazy_name' JOIN a v ON v.__path=k.__path AND v.parent=k.id AND v.field='value' WHERE m.__path=n.__path AND m.class_name='AsyncSchemaTransaction' AND m.name='ensure_polymorphic_columns_exist_async' AND v.kind='Constant' AND v.value_kind='str' AND v.value='ensure_polymorphic_columns_exist_lazy')")]
 for cls in names[:2]:checks.append((cls+' must not expose async-only ensure_polymorphic_columns_exist_async',f"EXISTS(SELECT 1 FROM first_methods m WHERE m.__path=n.__path AND m.class_name={q(cls)} AND m.name='ensure_polymorphic_columns_exist_async')"))
 complete="(SELECT count(*) FROM first_classes c WHERE c.__path=n.__path AND c.name IN "+literals(names)+')=3'
 sql=[row('CONN000',"'missing schema transaction classes: '||(SELECT group_concat(name,', ') FROM ("+missing+") required WHERE NOT EXISTS(SELECT 1 FROM first_classes c WHERE c.__path=n.__path AND c.name=required.name))",'a n',"n.kind='Module' AND NOT ("+complete+')',order='0')]
 sql.extend(row('CONN000',q(msg),'a n',"n.kind='Module' AND "+complete+' AND ('+condition+')',order=str(i+1)) for i,(msg,condition) in enumerate(checks))
 return sql

def candidate(root):
 from . import service_repository as repo
 c=constants(root/'scripts/lint_connection_service_architecture.py');s=stages(c)+repo.stages(c)
 analyze_query=' UNION ALL '.join(analyze(c));facade_query=' UNION ALL '.join(facade())
 sql_query=repo.sql_services(c);backend_query=repo.backend_cores(c);cross_query=repo.cross_owners()
 s.extend([S('service_analysis',analyze_query),S('service_sql',sql_query),S('service_backend',backend_query),S('service_cross',cross_query)])
 analyze_query='SELECT * FROM service_analysis';sql_query='SELECT * FROM service_sql';backend_query='SELECT * FROM service_backend';cross_query='SELECT * FROM service_cross'
 conn_query="SELECT * FROM ("+analyze_query+") WHERE issue='CONN103'"
 production=' UNION ALL '.join('SELECT *, '+str(group)+' api_group FROM ('+query+')' for group,query in [(0,sql_query),(2,backend_query),(3,'SELECT * FROM ('+analyze_query+') WHERE '+repo.BROAD.replace('__path','path')),(4,cross_query),(5,"SELECT * FROM ("+conn_query+") WHERE path IN ('impl/remote/connection.py','impl/read_through/connection.py')")])
 main=clause('connection-services',s,{'$option':'entryPoint','cases':{'analyze_source':analyze_query,'_lint_schema_transaction_facades_source':facade_query,'_lint_sql_services':sql_query,'_lint_backend_cores':backend_query,'_lint_duplicate_service_ownership_across_files':cross_query,'_lint_forbidden_connection_level_schema_methods_for_files':conn_query},'default':production},partition=False)
 fac=clause('schema-transaction-facades',s,'SELECT * FROM ('+facade_query+") WHERE path='l2000_connection/schema_transaction.py'")
 # This clause is a separate public entry. It runs only in the repository analyzer.
 fac['relational']['inputs']['gate']['evidence']['query']['ast']['rule']=A(K('module'),{'filePath':{'regex':r'^l2000_connection/schema_transaction\.py$'}},{'$option':'entryPoint','cases':{'all':TRUE},'default':FALSE})
 fac['relational']['query']={'$option':'entryPoint','cases':{'all':'SELECT *,1 api_group FROM ('+fac['relational']['query']+')'},'default':'SELECT * FROM ('+facade_query+') WHERE 0'}
 item=document('connection_service_architecture',[main,fac],['l2000_connection/**/*.py','impl/common/l2200_sql_dialect/**/*.py','impl/{sqlite,postgres,mariadb,remote,read_through}/connection.py','impl/common/l5150_fts_polyfill/manager.py'])
 item['scope']['exclude']=['**/tests/**','**/test_*.py','**/*_test.py']
 return item
